#include <math.h>
#include <stddef.h>
#include <stdint.h>
#define ETS_POINTS 8
#define ETS_NODES 15
#define ETS_EDGES 28
typedef struct{int left,right,rep;uint64_t mask;double cx,cy,rx,ry,r,span;}EtsNode;
typedef struct{double x[8],y[8];EtsNode node[15];int used,n,edge_count,overflow;double separation;double edges[56];}EtsCtx;
static int less(const EtsCtx*c,int a,int b,int axis){double a0=axis?c->y[a]:c->x[a],b0=axis?c->y[b]:c->x[b],a1=axis?c->x[a]:c->y[a],b1=axis?c->x[b]:c->y[b];return a0<b0||(a0==b0&&(a1<b1||(a1==b1&&a<b)));}
static int build(EtsCtx*c,uint64_t mask){int at=c->used++,members[8],n=0;double xmin=0,xmax=0,ymin=0,ymax=0;int rep=8;for(int i=0;i<c->n;i++)if(mask&(UINT64_C(1)<<i)){if(!n){xmin=xmax=c->x[i];ymin=ymax=c->y[i];}else{xmin=fmin(xmin,c->x[i]);xmax=fmax(xmax,c->x[i]);ymin=fmin(ymin,c->y[i]);ymax=fmax(ymax,c->y[i]);}members[n++]=i;if(i<rep)rep=i;}EtsNode*q=&c->node[at];q->left=q->right=-1;q->mask=mask;q->rep=rep;q->cx=(xmin+xmax)/2;q->cy=(ymin+ymax)/2;q->rx=(xmax-xmin)/2;q->ry=(ymax-ymin)/2;q->r=hypot(q->rx,q->ry);q->span=fmax(xmax-xmin,ymax-ymin);if(n==1)return at;int axis=xmax-xmin>=ymax-ymin?0:1;for(int i=1;i<n;i++){int v=members[i],j=i;while(j>0&&less(c,v,members[j-1],axis)){members[j]=members[j-1];j--;}members[j]=v;}uint64_t lm=0,rm=0;int mid=n/2;for(int i=0;i<n;i++)if(i<mid)lm|=UINT64_C(1)<<members[i];else rm|=UINT64_C(1)<<members[i];int l=build(c,lm),r=build(c,rm);c->node[at].left=l;c->node[at].right=r;return at;}
static int separated(EtsCtx*c,int a,int b){EtsNode*u=&c->node[a],*v=&c->node[b];return hypot(u->cx-v->cx,u->cy-v->cy)-u->r-v->r>=c->separation*fmax(u->r,v->r);}
static void cross(EtsCtx*c,int a,int b){if(c->overflow)return;if(separated(c,a,b)){if(c->edge_count>=ETS_EDGES){c->overflow=1;return;}int u=c->node[a].rep,v=c->node[b].rep;if(u>v){int t=u;u=v;v=t;}c->edges[2*c->edge_count]=u;c->edges[2*c->edge_count+1]=v;c->edge_count++;return;}EtsNode*u=&c->node[a],*v=&c->node[b];if(u->left<0){cross(c,v->left,a);cross(c,v->right,a);}else if(v->left<0){cross(c,u->left,b);cross(c,u->right,b);}else if(u->span>v->span){cross(c,u->left,b);cross(c,u->right,b);}else{cross(c,a,v->left);cross(c,a,v->right);}}
static void visit(EtsCtx*c,int at){int l=c->node[at].left,r=c->node[at].right;if(l<0)return;visit(c,l);visit(c,r);cross(c,l,r);}
extern "C" int64_t euclidean_t_spanner(const double*in,size_t len,double*out,size_t cap){if(!in||len<6||len>18||!isfinite(in[0])||in[0]<2||in[0]>8||in[0]!=floor(in[0])||!isfinite(in[1])||in[1]<1.5||in[1]>4)return -1;int n=(int)in[0];if(len!=(size_t)(2+2*n))return -1;EtsCtx c={0};c.n=n;c.separation=4*(in[1]+1)/(in[1]-1);for(int i=0;i<n;i++){double x=in[2+2*i],y=in[3+2*i];if(!isfinite(x)||!isfinite(y)||fabs(x)>1000||fabs(y)>1000||x!=floor(x)||y!=floor(y))return -1;for(int j=0;j<i;j++)if(c.x[j]==x&&c.y[j]==y)return -1;c.x[i]=x;c.y[i]=y;}int root=build(&c,(UINT64_C(1)<<n)-1);visit(&c,root);if(c.overflow)return -1;size_t needed=(size_t)(1+2*c.edge_count);if(!out||cap<needed)return -2;out[0]=c.edge_count;for(int i=0;i<2*c.edge_count;i++)out[i+1]=c.edges[i];return (int64_t)needed;}
